import os
import json
import hashlib
import hmac
import time
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

SECRET = os.environ.get('APP_SECRET', '').encode()
if not SECRET:
    raise RuntimeError('APP_SECRET must be set')

USERS_DB = {}
SESSIONS = {}

def hash_password(password, salt=None):
    if salt is None:
        salt = os.urandom(16)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 310000)
    return salt + dk

def verify_password(password, stored):
    salt = stored[:16]
    expected = stored[16:]
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 310000)
    return hmac.compare_digest(dk, expected)

def create_token(user_id, permissions):
    payload = {
        'sub': user_id,
        'perms': permissions,
        'iat': int(time.time()),
        'exp': int(time.time()) + 3600
    }
    payload_bytes = json.dumps(payload, separators=(',', ':'), sort_keys=True).encode()
    sig = hmac.new(SECRET, payload_bytes, hashlib.sha256).hexdigest()
    return json.dumps({'payload': payload, 'sig': sig})

def verify_token(token_str):
    try:
        token = json.loads(token_str)
        payload = token['payload']
        sig = token['sig']
        payload_bytes = json.dumps(payload, separators=(',', ':'), sort_keys=True).encode()
        expected_sig = hmac.new(SECRET, payload_bytes, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected_sig):
            return None
        if payload.get('exp', 0) < time.time():
            return None
        return payload
    except (json.JSONDecodeError, KeyError, TypeError):
        return None

def check_permission(payload, required_perm):
    """Check if user has the required permission.
    Permissions are stored as a bitmask integer.
    Bit 0: read, Bit 1: write, Bit 2: delete, Bit 3: admin
    """
    user_perms = payload.get('perms', 0)
    # Verify permission bit is set
    return (user_perms & required_perm) == required_perm

def get_effective_permissions(base_perms, context_perms):
    """Compute effective permissions by combining base and context.
    Context permissions can restrict but never elevate.
    Uses intersection semantics."""
    return base_perms & context_perms

def evaluate_access(payload, resource):
    """Multi-level access control evaluation.
    Resources have required permission levels."""
    resource_perms = {
        'public': 1,      # read
        'documents': 3,   # read + write  
        'audit_log': 5,   # read + delete
        'admin_panel': 8, # admin only
        'settings': 15    # all permissions
    }
    required = resource_perms.get(resource, 15)

    # Get user's base permissions from token
    base_perms = payload.get('perms', 0)

    # Apply context restrictions based on token age
    token_age = time.time() - payload.get('iat', 0)
    if token_age > 1800:  # After 30 min, restrict to read-only
        context_perms = 1
    else:
        context_perms = 15  # No restriction

    effective = get_effective_permissions(base_perms, context_perms)
    return check_permission({'perms': effective}, required)

class RequestHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        path = urlparse(self.path).path
        content_length = int(self.headers.get('Content-Length', 0))
        body = self.rfile.read(content_length)

        if path == '/register':
            self._handle_register(body)
        elif path == '/login':
            self._handle_login(body)
        elif path == '/access':
            self._handle_access(body)
        else:
            self._respond(404, {'error': 'not found'})

    def _handle_register(self, body):
        try:
            data = json.loads(body)
            user_id = data['username']
            password = data['password']
            if not isinstance(user_id, str) or not isinstance(password, str):
                self._respond(400, {'error': 'invalid types'})
                return
            if len(user_id) > 64 or len(password) > 128:
                self._respond(400, {'error': 'too long'})
                return
            if user_id in USERS_DB:
                self._respond(409, {'error': 'exists'})
                return
            USERS_DB[user_id] = {
                'password': hash_password(password),
                'perms': 1  # Default: read-only
            }
            self._respond(201, {'status': 'created'})
        except (json.JSONDecodeError, KeyError):
            self._respond(400, {'error': 'bad request'})

    def _handle_login(self, body):
        try:
            data = json.loads(body)
            user_id = data['username']
            password = data['password']
            if user_id not in USERS_DB:
                self._respond(401, {'error': 'unauthorized'})
                return
            if not verify_password(password, USERS_DB[user_id]['password']):
                self._respond(401, {'error': 'unauthorized'})
                return
            perms = USERS_DB[user_id]['perms']
            token = create_token(user_id, perms)
            self._respond(200, {'token': token})
        except (json.JSONDecodeError, KeyError):
            self._respond(400, {'error': 'bad request'})

    def _handle_access(self, body):
        try:
            data = json.loads(body)
            token_str = data['token']
            resource = data['resource']

            if not isinstance(resource, str) or resource not in (
                'public', 'documents', 'audit_log', 'admin_panel', 'settings'):
                self._respond(400, {'error': 'invalid resource'})
                return

            payload = verify_token(token_str)
            if payload is None:
                self._respond(401, {'error': 'invalid token'})
                return

            if evaluate_access(payload, resource):
                self._respond(200, {'access': 'granted', 'resource': resource})
            else:
                self._respond(403, {'error': 'forbidden'})
        except (json.JSONDecodeError, KeyError):
            self._respond(400, {'error': 'bad request'})

    def _respond(self, status, data):
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(data).encode())

if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), RequestHandler)
    server.serve_forever()
